import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def phi(n):
    if n == 1:
        return 1
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def order(a, n):
    if math.gcd(a, n) != 1:
        # Should not happen based on problem constraints (m not div by 3)
        return 0 

    phi_n = phi(n)
    # Find all divisors of phi_n
    divisors = get_divisors(phi_n)

    k = phi_n
    for d in divisors:
        if d < k:
            # Check if a^d === 1 (mod n)
            if pow(a, d, n) == 1:
                k = d
                break
    return k

def calculate_N_C(m):
    if m == 1:
        return 0 # Set is empty

    # Find all divisors m' of m, m' > 1
    divisors_m_prime = [d for d in get_divisors(m) if d > 1]

    total_cycles = 0

    for m_prime in divisors_m_prime:
        # C(m') = phi(m') / ord_{m'}(3)

        # Since m is not divisible by 3, m_prime is not divisible by 3, so gcd(3, m_prime) = 1.
        phi_m_prime = phi(m_prime)

        # Calculate the order of 3 mod m_prime
        k = order(3, m_prime)

        # Number of cycles C(m')
        if k == 0: # Should not happen if gcd(3, m_prime) = 1 and m_prime > 1
            print(f"Error: k=0 for m'={m_prime}")
            continue

        C_m_prime = phi_m_prime // k
        total_cycles += C_m_prime

    return total_cycles

