import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def calculate_C(m_prime):
    if m_prime <= 1:
        return 0

    # Elements of the multiplicative group (Z/m'Z)*
    elements = [x for x in range(1, m_prime) if gcd(x, m_prime) == 1]

    if not elements:
        return 0

    visited = set()
    cycle_count = 0

    for start_element in elements:
        if start_element not in visited:
            cycle_count += 1
            current = start_element
            while current not in visited:
                visited.add(current)
                # The permutation is x -> 3x mod m'
                current = (3 * current) % m_prime
                if current == 0:
                    # This case should not occur as 3 is coprime to m'
                    # and current is in Z/m'Z
                    return -1 # Error indicator
    return cycle_count

def calculate_NC(m):
    if m <= 1 or m % 3 == 0:
        return None

    N_C = 0
    # Find all divisors m' of m
    divisors = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.append(i)
            if i * i != m:
                divisors.append(m // i)

    # Sum C(m') for m' > 1
    for m_prime in divisors:
        if m_prime > 1:
            c_m_prime = calculate_C(m_prime)
            if c_m_prime == -1:
                return None # Should not happen
            N_C += c_m_prime

    return N_C

